    "sections": [
      {
        "id": "overview",
        "title": "Overview",
        "package": "@astryxdesign/cli",
        "summary": "Astryx is built on modern web platform features: the [`Popover`](https://developer.mozilla.org/en-US/docs/Web/API/Popover_API) API, CSS anchor positioning, and CSS `light-dark()`. These let components stay small, accessible, and…"
      },
      {
        "id": "support-tiers",
        "title": "Support Tiers",
        "package": "@astryxdesign/cli",
        "summary": "Astryx officially supports Tier 1 and Tier 2. Tier 3 is best-effort: components will not crash, but positioning and theming may degrade."
      },
      {
        "id": "which-features-set-the-floor",
        "title": "Which Features Set the Floor",
        "package": "@astryxdesign/cli",
        "summary": "Only three modern features carry a browser requirement. Everything else Astryx uses (`:has()`, `color-mix()`, container queries, the `<dialog>` element) has been widely available since 2023 or earlier and needs no special handling."
      },
      {
        "id": "which-components-are-affected",
        "title": "Which Components Are Affected",
        "package": "@astryxdesign/cli",
        "summary": "Any component that opens a menu, popover, tooltip, or dropdown carries the browser requirement: it renders that surface in an overlay positioned against its trigger. That includes:"
      },
